#ifndef DOLPHIN_HW_REGS_H
#define DOLPHIN_HW_REGS_H

#include "dolphin/types.h"
/* FZGX_ADDR_* come from config/GFZE01/ldscript.tpl (generated by configure.py), shared with the link. */
#include "sdk_addresses.h"

/* Gekko locked-cache effective-address window. */
#define LC_BASE 0xE0000000u
/* GX write-gather FIFO address. */
#define GX_FIFO_BASE 0xCC008000u

/* OS low-memory globals as MWCC absolute objects (`T name : address;`): a read compiles to
   `lis rX, 0x8000; lwz rY, off(rX)` with no symbol or relocation, and the object is named, so it
   only aliases itself. MWCC accepts an identical redeclaration, so sources that still declare one
   locally keep compiling. (From deltawave784/fzgx, CC0.) */
u32 __OSBusClock : FZGX_ADDR___OSBusClock; /* 0x800000F8, the 162 MHz bus clock */
#define OS_BUS_CLOCK __OSBusClock
#define OS_TIMER_CLOCK (OS_BUS_CLOCK / 4)
u32 __OSTVMode : FZGX_ADDR___OSTVMode; /* 0x800000CC, VI_NTSC / VI_PAL / VI_MPAL / ... */

/* A VI register read at a folded literal address (`lis rX, 0xCC00; lhz rY, off(rX)`, no relocation),
   where retail did not go through the linker-defined __VIRegs. Indices are the SDK's u16 slots. */
#define VI_DTV_STAT 0x37
#define VI_REG_LITERAL(index) (*(vu16 *)(FZGX_ADDR___VIRegs + 2 * (index)))

#endif
